import pathlib

p = pathlib.Path('backend/app/services/agent/mcp/local_server.py')
src = p.read_text(encoding='utf-8')

# Update execute_command description
old_exec = 'description="\u5728\u4e3b\u7ec8\u7aef\u524d\u53f0\u6267\u884c\u4e00\u6761\u547d\u4ee4\u6216\u5411\u5f53\u524d\u4ea4\u4e92\u5f0f\u63a7\u5236\u53f0\u53d1\u9001\u8f93\u5165\u3002\u9002\u5408 shell \u77ed\u547d\u4ee4\u3001\u4ea4\u4e92\u5f0f\u670d\u52a1\uff08MC/Java server/REPL\uff09\u3001\u4ee5\u53ca\u63a7\u5236\u53f0\u540e\u7eed\u8f93\u5165\u3002\u4efb\u4f55\u4e0d\u900f\u660e\u7684\u547d\u4ee4\uff08\u672a\u77e5\u811a\u672c\u3001\u4e0d\u786e\u5b9a\u8017\u65f6\u7684\u64cd\u4f5c\uff09\u5148\u770b\u5185\u5bb9\u518d\u51b3\u5b9a\u7528\u54ea\u4e2a\u5de5\u5177\uff1a\u4e0b\u8f7d/\u5b89\u88c5/\u7f16\u8bd1\u7b49\u957f\u65f6\u64cd\u4f5c\u7528 run_job\uff0c\u542f\u52a8\u4ea4\u4e92\u5f0f\u670d\u52a1\u7528 execute_command\u3002apt/yum/pip/npm install\u3001apt update\u3001curl/wget \u4e0b\u8f7d\u3001make/cargo build \u7b49\u660e\u786e\u8017\u65f6\u7684\u547d\u4ee4\u5fc5\u987b\u7528 run_job\uff0c\u4e0d\u8981\u7528 execute_command\u3002\u4e00\u6b21\u53ea\u53d1\u4e00\u6761\u547d\u4ee4\uff0c\u4e0d\u8981\u7528 &&/||/; \u62fc\u63a5\u591a\u6b65\u3002\u53d1\u9519\u4e86\u53ef\u4ee5\u7528 interrupt_command (Ctrl+C) \u4e2d\u65ad\u518d\u91cd\u6765\u3002",'

new_exec = 'description="\u5728\u4e3b\u7ec8\u7aef\u524d\u53f0\u6267\u884c\u547d\u4ee4\u3002\u4ec5\u7528\u4e8e\u9700\u8981\u4ea4\u4e92\u7684\u573a\u666f\uff1a\u542f\u52a8\u670d\u52a1\u5668\uff08MC/Java server\uff09\u3001\u9700\u8981\u6309 Y \u786e\u8ba4\u6216\u8f93\u5165\u5185\u5bb9\u7684\u5b89\u88c5\u3001REPL\u3001\u4ee5\u53ca\u5411\u5df2\u8fd0\u884c\u7684\u63a7\u5236\u53f0\u53d1\u9001\u540e\u7eed\u6307\u4ee4\u3002\u4e0d\u9700\u8981\u4ea4\u4e92\u7684\u547d\u4ee4\uff08\u4e0b\u8f7d\u3001\u5e26 -y \u7684\u5b89\u88c5\u3001apt update\u3001\u7f16\u8bd1\u3001\u67e5\u8be2\uff09\u5168\u90e8\u7528 run_job\u3002\u4e0d\u786e\u5b9a\u662f\u5426\u9700\u8981\u4ea4\u4e92\u65f6\u5148 cat \u770b\u811a\u672c\u5185\u5bb9\u518d\u51b3\u5b9a\u3002\u4e00\u6b21\u53ea\u53d1\u4e00\u6761\u547d\u4ee4\uff0c\u53d1\u9519\u4e86\u7528 interrupt_command (Ctrl+C) \u4e2d\u65ad\u518d\u91cd\u6765\u3002",'

assert old_exec in src, 'execute_command desc not found'
src = src.replace(old_exec, new_exec, 1)
p.write_text(src, encoding='utf-8')
print('execute_command desc updated OK')
